 <!doctype html>
 <html lang="en">
 <head>
   <meta charset="utf-8">
   <meta name="viewport" content="width=device-width, initial-scale=1">
   <title>Support contact form</title>
   <style>
     :root {
       color-scheme: dark;
       --color-bg: #0b1020;
       --color-surface: #121a2f;
       --color-surface-alt: #18233d;
       --color-text: #edf2ff;
       --color-muted-text: #b8c2e0;
       --color-border: #334064;
       --color-border-strong: #5c6da3;
       --color-focus: #8ab4ff;
       --color-danger: #ff8b8b;
       --color-danger-border: #d96a6a;
       --color-success: #84e0a0;
       --shadow: 0 20px 60px #050816;
     }

     * {
       box-sizing: border-box;
     }

     html {
       scroll-behavior: smooth;
     }

     body {
       margin: 0;
       min-height: 100vh;
       font: 16px/1.5 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       color: var(--color-text);
       background:
         radial-gradient(circle at top, #16213d 0, #0b1020 55%),
         var(--color-bg);
     }

     a {
       color: var(--color-focus);
     }

     .skip-link {
       position: absolute;
       top: 0.75rem;
       left: 0.75rem;
       z-index: 10;
       padding: 0.75rem 1rem;
       border-radius: 0.75rem;
       background: var(--color-surface);
       color: var(--color-text);
       transform: translateY(-200%);
       transition: transform 0.2s ease;
     }

     .skip-link:focus {
       transform: translateY(0);
     }

     main {
       width: min(100%, 70rem);
       margin: 0 auto;
       padding: 2rem 1rem 3rem;
     }

     .page-shell {
       display: grid;
       gap: 1.5rem;
       align-items: start;
     }

     .hero {
       padding: 0.5rem 0.25rem;
       max-width: 42rem;
     }

     .eyebrow {
       margin: 0 0 0.5rem;
       color: var(--color-focus);
       font-size: 0.875rem;
       font-weight: 700;
       letter-spacing: 0.08em;
       text-transform: uppercase;
     }

     h1 {
       margin: 0;
       font-size: clamp(2rem, 4vw, 3.25rem);
       line-height: 1.1;
     }

     .lead {
       margin: 1rem 0 0;
       max-width: 38rem;
       color: var(--color-muted-text);
       font-size: 1.05rem;
     }

     .form-card {
       padding: clamp(1.25rem, 2vw, 2rem);
       border: 1px solid var(--color-border);
       border-radius: 1.25rem;
       background: linear-gradient(180deg, var(--color-surface), var(--color-surface-alt));
       box-shadow: var(--shadow);
     }

     form {
       display: grid;
       gap: 1rem;
     }

     .form-field {
       display: grid;
       gap: 0.5rem;
     }

     label {
       font-weight: 650;
       color: var(--color-text);
     }

     .required-mark {
       color: var(--color-danger);
     }

     input {
       width: 100%;
       padding: 0.9rem 1rem;
       border: 1px solid var(--color-border);
       border-radius: 0.875rem;
       background: #0d1426;
       color: var(--color-text);
       font: inherit;
     }

     input::placeholder {
       color: var(--color-muted-text);
     }

     input:hover {
       border-color: var(--color-border-strong);
     }

     input:focus,
     button:focus {
       outline: 3px solid var(--color-focus);
       outline-offset: 3px;
     }

     input[aria-invalid="true"] {
       border-color: var(--color-danger-border);
     }

     .field-help,
     .field-error,
     .form-status {
       margin: 0;
       font-size: 0.95rem;
     }

     .field-help {
       color: var(--color-muted-text);
     }

     .field-error {
       color: var(--color-danger);
       font-weight: 600;
     }

     .form-status {
       min-height: 1.5em;
       color: var(--color-success);
       font-weight: 600;
     }

     .actions {
       display: flex;
       flex-wrap: wrap;
       gap: 0.75rem;
       align-items: center;
       margin-top: 0.25rem;
     }

     button {
       border: 1px solid #6a80c0;
       border-radius: 0.875rem;
       padding: 0.95rem 1.25rem;
       background: linear-gradient(180deg, #4f72d8, #3858bb);
       color: #ffffff;
       font: inherit;
       font-weight: 700;
       cursor: pointer;
     }

     button:hover {
       border-color: #92a8e8;
       background: linear-gradient(180deg, #5f7fe0, #4968ce);
     }

     button:active {
       transform: translateY(1px);
     }

     @media (min-width: 52rem) {
       .page-shell {
         grid-template-columns: 1.05fr 0.95fr;
         gap: 2rem;
       }

       .hero {
         padding-top: 2rem;
       }
     }

     @media (forced-colors: active) {
       :root {
         --color-bg: Canvas;
         --color-surface: Canvas;
         --color-surface-alt: Canvas;
         --color-text: CanvasText;
         --color-muted-text: CanvasText;
         --color-border: CanvasText;
         --color-border-strong: CanvasText;
         --color-focus: Highlight;
         --color-danger: CanvasText;
         --color-danger-border: CanvasText;
         --color-success: CanvasText;
       }

       .form-card {
         box-shadow: none;
       }

       input,
       button {
         forced-color-adjust: auto;
         background: ButtonFace;
         color: ButtonText;
         border-color: ButtonBorder;
       }

       .field-error,
       .form-status,
       .field-help,
       .eyebrow {
         color: CanvasText;
       }
     }
   </style>
 </head>
 <body>
   <a class="skip-link" href="#support-form">Skip to contact form</a>

   <main id="main-content">
     <div class="page-shell">
       <section class="hero" aria-labelledby="page-title">
         <p class="eyebrow">Support</p>
')

