   <a class="skip-link" href="#support-form">Skip to contact form</a>

   <main id="main-content">
     <div class="page-shell">
       <section class="hero" aria-labelledby="page-title">
         <p class="eyebrow">Support</p>
         <h1 id="page-title">Contact our support team</h1>
         <p class="lead">Send your details and we&apos;ll get back to you by email. Full name and email are required; phone is optional.</p>
       </section>

       <section class="form-card">
         <form id="support-form" novalidate>
           <div class="form-field">
             <label for="full-name">Full name <span class="required-mark" aria-hidden="true">*</span></label>
             <input id="full-name" name="fullName" type="text" autocomplete="name" required>
             <p class="field-error" id="full-name-error" hidden></p>
           </div>

           <div class="form-field">
             <label for="email-address">Email address <span class="required-mark" aria-hidden="true">*</span></label>
             <input id="email-address" name="email" type="email" autocomplete="email" required>
             <p class="field-error" id="email-address-error" hidden></p>
           </div>

           <div class="form-field">
             <label for="phone-number">Phone number</label>
             <input id="phone-number" name="phone" type="tel" autocomplete="tel" inputmode="tel" aria-describedby="phone-number-help">
             <p class="field-help" id="phone-number-help">Format: +1 555 123 4567, (555) 123-4567, or similar international phone number.</p>
             <p class="field-error" id="phone-number-error" hidden></p>
           </div>

           <p class="form-status" id="form-status" role="status" aria-live="polite" hidden></p>

           <div class="actions">
             <button type="submit">Send message</button>
           </div>
         </form>
       </section>
     </div>
   </main>

   <script>
     const form = document.getElementById('support-form');
     const status = document.getElementById('form-status');
     const fields = [
       {
         input: document.getElementById('full-name'),
         error: document.getElementById('full-name-error'),
         validate: (value) => value.trim().length > 0 ? '' : 'Error: Enter your full name.'
       },
       {
         input: document.getElementById('email-address'),
         error: document.getElementById('email-address-error'),
         validate: (value, input) => {
           if (value.trim().length === 0) return 'Error: Enter your email address.';
           return input.validity.valid ? '' : 'Error: Enter a valid email address, like name@example.com.';
         }
       },
       {
         input: document.getElementById('phone-number'),
         error: document.getElementById('phone-number-error'),
         validate: (value) => {
           const trimmed = value.trim();
           if (!trimmed) return '';
           const digits = trimmed.replace(/\D/g, '');
           return digits.length >= 7 ? '' : 'Error: Enter a phone number in the expected format, such as +1 555 123 4567.';
         }
       }
     ];

     const errorIds = new Map(fields.map((field) => [field.input.id, field.error.id]));
     let submitAttempted = false;

     function updateDescribedBy(field, includeError) {
       const helpIds = {
         'phone-number': ['phone-number-help']
       };

       const ids = [...(helpIds[field.input.id] || [])];
       if (includeError) ids.push(field.error.id);
       if (ids.length > 0) {
         field.input.setAttribute('aria-describedby', ids.join(' '));
       } else {
         field.input.removeAttribute('aria-describedby');
       }
     }

     function setFieldState(field, message) {
       const isInvalid = Boolean(message);
       if (isInvalid) {
         field.input.setAttribute('aria-invalid', 'true');
       } else {
         field.input.removeAttribute('aria-invalid');
       }
       field.error.textContent = message;
       field.error.hidden = !isInvalid;
       updateDescribedBy(field, isInvalid);
     }

     function validateField(field) {
       const message = field.validate(field.input.value, field.input);
       setFieldState(field, message);
       return !message;
     }

     function validateForm() {
       let firstInvalid = null;
       let isValid = true;

       for (const field of fields) {
         const fieldValid = validateField(field);
         if (!fieldValid && !firstInvalid) {
           firstInvalid = field.input;
         }
         isValid = isValid && fieldValid;
       }

       if (!isValid && firstInvalid) {
         firstInvalid.focus();
       }

       return isValid;
     }

     for (const field of fields) {
       field.input.addEventListener('input', () => {
         if (submitAttempted || field.input.getAttribute('aria-invalid') === 'true') {
           validateField(field);
         }
       });

       field.input.addEventListener('blur', () => {
         if (submitAttempted) {
           validateField(field);
         }
       });
     }

     form.addEventListener('submit', (event) => {
       event.preventDefault();
       submitAttempted = true;
       status.hidden = true;
       status.textContent = '';

       if (!validateForm()) {
         return;
       }

       form.reset();
       for (const field of fields) {
         setFieldState(field, '');
       }
       status.textContent = 'Thanks — your message is ready to send.';
       status.hidden = false;
     });
