            <label for="email-address">Email address <span class="required-mark" aria-hidden="true">*</span></label>
            <input id="email-address" name="email" type="email" autocomplete="email" required>
            <p class="field-error" id="email-address-error" hidden></p>
          </div>

          <div class="form-field">
            <label for="phone-number">Phone number</label>
            <input id="phone-number" name="phone" type="tel" autocomplete="tel" inputmode="tel" aria-describedby="phone-number-help">
