  <script>
    const form = document.getElementById('support-form');
    const status = document.getElementById('form-status');
    const fields = [
      {
        input: document.getElementById('full-name'),
        error: document.getElementById('full-name-error'),
        validate: (value) => value.trim().length > 0 ? '' : 'Error: Enter your full name.'
      },
      {
        input: document.getElementById('email-address'),
        error: document.getElementById('email-address-error'),
        validate: (value, input) => {
          if (value.trim().length === 0) return 'Error: Enter your email address.';
          return input.validity.valid ? '' : 'Error: Enter a valid email address, like name@example.com.';
        }
      },
      {
        input: document.getElementById('phone-number'),
        error: document.getElementById('phone-number-error'),
        validate: (value) => {
          const trimmed = value.trim();
          if (!trimmed) return '';
          const digits = trimmed.replace(/\D/g, '');
          return digits.length >= 7 ? '' : 'Error: Enter a phone number in the expected format, such as +1 555 123 4567.';
        }
      }
    ];

    let submitAttempted = false;

    function updateDescribedBy(field, includeError) {
      const helpIds = {
        'phone-number': ['phone-number-help']
      };

      const ids = [...(helpIds[field.input.id] || [])];
      if (includeError) ids.push(field.error.id);
      if (ids.length > 0) {
