    function validateField(field) {
      const message = field.validate(field.input.value, field.input);
      setFieldState(field, message);
      return !message;
    }

    function validateForm() {
      let firstInvalid = null;
      let isValid = true;

      for (const field of fields) {
        const fieldValid = validateField(field);
        if (!fieldValid && !firstInvalid) {
          firstInvalid = field.input;
        }
        isValid = isValid && fieldValid;
      }

      if (!isValid && firstInvalid) {
        firstInvalid.focus();
      }

      return isValid;
    }

    for (const field of fields) {
      field.input.addEventListener('input', () => {
        if (submitAttempted || field.input.getAttribute('aria-invalid') === 'true') {
          validateField(field);
        }
      });

      field.input.addEventListener('blur', () => {
        if (submitAttempted) {
          validateField(field);
        }
      });
    }

    form.addEventListener('submit', (event) => {
      event.preventDefault();
      submitAttempted = true;
      status.hidden = true;
      status.textContent = '';

      if (!validateForm()) {
        return;
      }

      form.reset();
      for (const field of fields) {
        setFieldState(field, '');
      }
      status.textContent = 'Thanks — your message is ready to send.';
      status.hidden = false;
